UPDATE kg_edges SET attrs_json='{"role":"상임부회장","count":10,"confidence":0.95,"roles":{"상임부회장":10},"years":["1996","2001","2002","2003","2004"],"evidence":["안고등학교에서 열린 준공식에는 이익창 교육장, 신남규 체육회 상임부회장 김세호 총동창회장 등 관내 기관 단체장과","참을 결의해 관심이 집중되고 있다. 지난 9일 태안군 체육회(상임부회장 신남규)는 체육회 사무실에서 체육회 이사와","청남도민체육대회(10∼12일)를 하루 앞둔 지난 9일 태안군체육회(상임부회장 신남규)가 선수단 결단식을 갖고 총 16개"],"sources":["365","394","741","1934","2776"],"role_fixed":"2026-08-28 접두잘림 교정"}', updated_at=datetime('now') WHERE id='e:belongs:신남규__org:taean-cci';
UPDATE kg_edges SET attrs_json='{"role":"부군수","count":13,"confidence":0.95,"roles":{"부군수":13},"years":["2010","2011"],"evidence":["야 한다는 목소리도 나왔다 이두훈 부군수는 축제가 끝난지 3개","밝혔다. 이날 출범식에는 이두훈 부군수를 비롯해 허종일 군","로 제시했다. 이 자리에서 이두훈 부군수는 일부 민원이 지연되"],"sources":["18444","18852","18858","19295","19506"],"role_fixed":"2026-08-28 접두잘림 교정"}', updated_at=datetime('now') WHERE id='e:belongs:이두훈__org:taean-gov';
