UPDATE kg_edges SET attrs_json='{"role":"상임부회장","count":20,"confidence":0.95,"roles":{"의장":6,"상임부회장":14},"years":["2004","2005","2006","2007","2019"],"evidence":["발전을 위해 지속적인 협조를 부탁했다. 특히 태안군 체육회(상임부회장 이종국)·축구협회(협회장 김종직)와 극회","여일 앞으로 다가온 제 56회 충남 도민체전을 앞두고 태안군체육회(상임부회장 이종국)가 선전을 다짐하는 필승 결의대회를","다해 달라”고 말했다. 이어 최상린 대표이사가 이종국 체육회 상임부회장에 선전을 기원하는 꽃다발을 전달하고 참석자"],"sources":["3422","3557","3688","4053","4224"],"role_fixed":"2026-08-28 접두잘림 교정"}', updated_at=datetime('now') WHERE id='e:belongs:이종국__org:taean-cci';
