UPDATE kg_edges SET attrs_json='{"role":"부의장","count":6,"confidence":0.9,"roles":{"부의장":5,"군의원":1},"years":["1995","1996","1998","2007"],"evidence":["스로 알려져 안타까움을 더하고 있다. 숨진 최씨는 전 태안군의회 최진환 부의장의 셋째 아들로 평소에도 어려운 이웃들을","의 경우 초선의 문제동의장 최진환 부의장 박남규 의원 태안군의회 제2대 전반기 의정운영을 이끌어 오면서 그동안 군민의","을의 안녕과 무사고를 기원하는 최경섭 도의원, 최진환 군의회 부의장 등 기관장과 주민 등 1백여 명의 참여 속에"],"sources":["10936","90009774","90018097","90022137","90023075"],"role_fixed":"2026-08-28 접두잘림 교정"}', updated_at=datetime('now') WHERE id='e:belongs:최진환__org:taean-council';
