UPDATE kg_edges SET attrs_json='{"role":"부군수","count":57,"confidence":0.95,"roles":{"부군수":57},"years":["2005","2006","2007","2011"],"evidence":["면 좋겠다”고 말했다. 허정회 태안부군수는 “이 사업이 청각장","1시 농협 2층 회의실에서 허정회 부군수, 정지근 군의원, 이","를 개최했다. 이 자리에는 허정회 부군수를 비롯 각 읍·면장"],"sources":["4151","4212","4455","4472","4536"],"role_fixed":"2026-08-28 접두잘림 교정"}', updated_at=datetime('now') WHERE id='e:belongs:허정회__org:taean-gov';